CREATE TABLE `promociones` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `titulo` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `descripcion` text NOT NULL,
  `tipo` varchar(20) NOT NULL DEFAULT 'oferta',
  `descuento` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `activa` tinyint(1) NOT NULL DEFAULT 1,
  `vigente_desde` date DEFAULT NULL,
  `vigente_hasta` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `promociones_slug_unique` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `promociones` WRITE;
/*!40000 ALTER TABLE `promociones` DISABLE KEYS */;
INSERT INTO `promociones` VALUES (1,'Oferta · Uchus en Escabeche','oferta-uchus-en-escabeche','Picante redondo con precio especial. Aprovechando el próximo lote: encargá el tuyo y lo tenés fresco en dos semanas.','oferta',15,1,NULL,'2026-10-15','2026-09-26 21:26:05','2026-09-26 21:26:05'),(2,'Combo Parrillera · Ahorro Bs 25','combo-parrillera-ahorro-bs-25','Cebolla morada, jalapeños y escabeche para pique macho. Todo lo que necesitás para arrancar la parrilla bien.','combo',18,1,NULL,'2026-12-31','2026-09-26 21:26:05','2026-09-26 21:26:05'),(3,'Temporada · Habanero Ahumado','temporada-habanero-ahumado','Edición limitada elaborada con habaneros de huerta. Poca producción, sabor muy nuestro.','temporada',0,1,NULL,'2026-11-30','2026-09-26 21:26:05','2026-09-26 21:26:05'),(4,'Últimos frascos · Pepinos con Mostaza','ultimos-frascos-pepinos-con-mostaza','Quedan 3 frascos del lote de julio. Cuando terminen, la producción se reinicia en octubre.','limitado',10,1,NULL,'2026-10-05','2026-09-26 21:26:05','2026-09-26 21:26:05'),(5,'Oferta · Escabeche para Pique Macho','oferta-escabeche-para-pique-macho','Escabeche de ají colorado, cebolla morada y morrón asado. El condimento que estaba faltando en tu asado.','oferta',12,1,NULL,'2026-10-31','2026-09-26 21:26:05','2026-09-26 21:26:05');
