DROP TABLE IF EXISTS `resenas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `resenas` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `producto_id` bigint(20) unsigned NOT NULL,
  `autor` varchar(255) NOT NULL,
  `estrellas` tinyint(3) unsigned NOT NULL,
  `texto` text NOT NULL,
  `visible` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `resenas_producto_id_visible_index` (`producto_id`,`visible`),
  CONSTRAINT `resenas_producto_id_foreign` FOREIGN KEY (`producto_id`) REFERENCES `productos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `resenas` WRITE;
/*!40000 ALTER TABLE `resenas` DISABLE KEYS */;
INSERT INTO `resenas` VALUES (1,1,'Valentina R.',5,'La cebolla va tremenda con la parrilla. Se nota que es casera de verdad, nada de sabor raro como los industrializados.',1,'2026-09-18 16:00:00','2026-09-26 21:26:05'),(2,1,'Marcos G.',5,'Le pongo a todas las hamburguesas que hago. La textura es increíble, sigue crocante.',1,'2026-09-11 16:00:00','2026-09-26 21:26:05'),(3,2,'Sofía A.',4,'Excelente escabeche, tiene buen picor. Lo usé para unos tacos y quedaron bárbaros.',1,'2026-09-14 16:00:00','2026-09-26 21:26:05'),(4,3,'Damián L.',5,'Ojo que pica en serio. Si te gusta el picante, este es el que tenés que llevar a la parrilla.',1,'2026-09-06 16:00:00','2026-09-26 21:26:05'),(5,8,'Familia Torres',5,'Compramos el combo para el asado del domingo y fue un éxito. Se nos terminó en dos horas.',1,'2026-09-20 16:00:00','2026-09-26 21:26:05'),(6,11,'Laura M.',5,'El relish cambió mis hamburguesas. Sabor a casero, te juro.',1,'2026-09-09 16:00:00','2026-09-26 21:26:05'),(7,5,'Andrés P.',4,'Muy bueno, tierno y sin picar. Ideal para la carne asada.',1,'2026-08-30 16:00:00','2026-09-26 21:26:05'),(8,4,'Carla B.',5,'De lo mejor que probé. La edición limitada vale la pena.',1,'2026-09-21 16:00:00','2026-09-26 21:26:05'),(9,7,'Nico V.',5,'Justo lo que buscaba para el pique. El morrón asado le da una vuelta tremenda.',1,'2026-09-15 16:00:00','2026-09-26 21:26:05'),(10,6,'Rocío S.',4,'Los pepinos de siempre, muy buenos. Ojalá hagan más seguido.',1,'2026-08-25 16:00:00','2026-09-26 21:26:05');
/*!40000 ALTER TABLE `resenas` ENABLE KEYS */;
UNLOCK TABLES;
